from collections.abc import Iterable, Sequence, Sized
from functools import singledispatch

@singledispatch
def go(x):
    return "obj"

@go.register
def _(x: Sized):
    return "sized"

@go.register
def _(x: Iterable):
    return "iter"

@go.register
def _(x: Sequence):
    return "seq"

@go.register
def _(x: int):
    return "int"

out = []
for v in [1, True, "a", [1], (1,), {1}, {1: 2}, iter([1]), 3.5, b"z", range(2)]:
    try:
        out.append(go(v))
    except RuntimeError:
        out.append("AMB")
print(",".join(out))
```

